  const upcomingTicket = createTicket('upcoming', 'booked');
  const completedTicket = createTicket(
    'completed',
    'completed',
    'IN_PERSON'
  );
  const cancelledTicket = createTicket('cancelled', 'clientCancelled');

  mockTicketList.mockImplementation(
    ({ statusGroup }: { statusGroup: string }): Promise<Ticket[]> => {
      if (statusGroup === 'upcoming') {
        return Promise.resolve([upcomingTicket]);
      }
      if (statusGroup === 'completed') {
        return Promise.resolve([completedTicket]);
      }
      if (statusGroup === 'cancelled') {
        return Promise.resolve([cancelledTicket]);
      }
      return Promise.resolve([]);
    }
  );

